@RequiredArgsConstructor
@Getter
public enum Monster
{
	// Brothers
	Ahrim( "Ahrim the Blighted", 98, NpcID.AHRIM_THE_BLIGHTED, Varbits.BARROWS_KILLED_AHRIM ),
	Dharok( "Dharok the Wretched", 115, NpcID.DHAROK_THE_WRETCHED, Varbits.BARROWS_KILLED_DHAROK ),
